/** 测试用 stub: 模拟真实 toFetchHandler 的信封分派 (仅测试) */
export function toFetchHandler(api) {
  return {
    async fetch(request) {
      const url = new URL(request.url);
      const path = url.pathname;
      if (path === '/api/events.mux' || path === '/api/events.host') {
        if (typeof api.events?.[path.split('/')[2]] === 'function') {
          const value = await api.events[path.split('/')[2]]();
          return new Response(JSON.stringify(value), { headers: { 'content-type': 'application/json' } });
        }
      }
      if (request.method !== 'POST') return new Response('not found', { status: 404 });
      let body;
      try { body = await request.json(); } catch { return new Response('bad json', { status: 400 }); }
      const method = body.method;
      if (method && typeof api[method] === 'function') {
        const result = await api[method](body.payload, request.signal);
        return Response.json({ rpcId: body.rpcId, result });
      }
      return new Response('not found', { status: 404 });
    },
  };
}
